import os
import glob

print("CWD:", os.getcwd())
print("Files in cwd:", os.listdir("."))

# Search for report.pdf in likely locations
hits = []
for root in [".", "/tmp", "/workspace", "/app", "/data", "/home"]:
    if os.path.isdir(root):
        for p in glob.glob(os.path.join(root, "**", "report.pdf"), recursive=True):
            hits.append(p)
print("Found report.pdf at:", hits)

# Check libraries
